findings.current_code:
  run absent-inspect docker inspect "$CID"
  [ "$LAST_RC" -eq 0 ] && { note "container still present"; crc=1; }
  run absent-by-label sh -c "docker ps -a -q --filter label=ama.rpi.task=$TASK --filter name=$NAME | wc -l"
  [ "$(cat "$L/$LAST.out" 2>/dev/null)" != 0 ] && { note "owner label/name not empty"; crc=1; }
fi
[ -f "$X/private/sa.pw" ] && { run secret-scan $SETUP scan; [ "$LAST_RC" -ne 0 ] && crc=1; }
run unlink-private $SETUP unlink
